        fields.append("")
    return {"name": fields[0], "cents": fields[1], "currency": fields[2]}
'''
open('billing/api.py','w').write(api)
for f in sorted(glob.glob('billing/*.py')):
    if f.endswith('api.py') or f.endswith('__init__.py'):
        continue
    txt=open(f).read()
    new=txt.replace('from .api import parse\n','from .api import parse_row\n').replace('= parse(text)','= parse_row(text)').replace('row["amount"]','row["cents"]')
    if new!=txt:
        open(f,'w').write(new)
print('done')

